#!/usr/bin/env bash
# GENERATED by /slava:util:scriptify from .claude/commands/slava/script/claude-sync-download.md
# Covers the deterministic tail (original steps 3 + 4). Steps 1-2 (browser export
# click, Gmail MCP poll) stay INLINE in the twin — they need the model's tool context.
#
# Contract:  $@ = one or more claude.ai export download URLs, OR a single path to the
#            manifest-*.json the export mail links to (whose export_url fields are used).
#            Since 2026-09 an export is FIVE files (conversations, projects, memories,
#            design_chats, light_metadata), each URL usable exactly once.
# DRY_RUN=1  skips `open`, the download wait, and the importer — validates args only.
set -euo pipefail

DESKTOP="$HOME/Desktop"
DOWNLOADS="$HOME/Downloads"
WAIT_SECS="${WAIT_SECS:-90}"   # multi-file export takes longer than the old single zip

if [ "$#" -eq 0 ]; then
  echo "ERROR: missing args. Usage: $0 <export-url> [<export-url>...]" >&2
  echo "                    or: $0 /path/to/manifest-<uuid>-....json" >&2
  exit 1
fi

# --- resolve args into a URL list -------------------------------------------
URLS=()
if [ "$#" -eq 1 ] && [ -f "$1" ]; then
  # manifest file: pull every export_url out of it
  while IFS= read -r u; do URLS+=("$u"); done < <(
    python3 -c '
import json,sys
m=json.load(open(sys.argv[1]))
for d in m.get("data_files",[]):
    if d.get("export_url"): print(d["export_url"])
' "$1")
  if [ "${#URLS[@]}" -eq 0 ]; then
    echo "ERROR: no export_url entries in manifest $1" >&2
    exit 1
  fi
  echo "Manifest $1: ${#URLS[@]} export URL(s)"
else
  URLS=("$@")
fi

for u in "${URLS[@]}"; do
  case "$u" in
    https://claude.ai/export/*/download/*) : ;;
    *) echo "ERROR: not a claude.ai export download URL: $u" >&2; exit 1 ;;
  esac
done

MARKER="$(mktemp)"

if [ "${DRY_RUN:-}" = "1" ]; then
  for u in "${URLS[@]}"; do echo "[DRY_RUN] would: open \"$u\""; done
  echo "[DRY_RUN] would: wait up to ${WAIT_SECS}s for export zips in $DESKTOP or $DOWNLOADS"
  echo "[DRY_RUN] would: copy any zips landing on the Desktop to $DOWNLOADS/"
  echo "[DRY_RUN] would: run the importer"
  rm -f "$MARKER"
  echo "[DRY_RUN] args valid; control flow OK (${#URLS[@]} url(s))"
  exit 0
fi

# --- step 3: trigger native browser downloads (logged-in Chrome, Cloudflare-gated) ---
for u in "${URLS[@]}"; do
  echo "Opening: $u"
  open "$u"
  sleep 2   # stagger so Chrome does not drop concurrent downloads
done

# Both export shapes: `conversations-000.zip` & friends (2026-09+) and the
# legacy single `data-*.zip`.
find_zips() {
  find "$DESKTOP" "$DOWNLOADS" -maxdepth 1 \
    \( -name 'conversations-*.zip' -o -name 'projects-*.zip' \
       -o -name 'memories-*.zip' -o -name 'design_chats-*.zip' \
       -o -name 'light_metadata-*.zip' -o -name 'data-*.zip' \) \
    -newer "$MARKER" 2>/dev/null | sort
}

echo "Waiting up to ${WAIT_SECS}s for ${#URLS[@]} download(s)..."
FOUND=0
STABLE=0
for _ in $(seq 1 "$WAIT_SECS"); do
  sleep 1
  N="$(find_zips | wc -l | tr -d ' ')"
  if [ "$N" -gt 0 ] && [ "$N" -eq "$FOUND" ]; then
    STABLE=$((STABLE + 1))
    [ "$STABLE" -ge 5 ] && break     # count held steady — downloads settled
  else
    STABLE=0
  fi
  FOUND="$N"
done

ZIPS="$(find_zips)"
rm -f "$MARKER"

if [ -z "$ZIPS" ]; then
  echo "ERROR: no export zip appeared on $DESKTOP or $DOWNLOADS within ${WAIT_SECS}s" >&2
  echo "       (download may have failed, or the single-use URLs were already spent)." >&2
  exit 2
fi

echo "Downloaded $(printf '%s\n' "$ZIPS" | wc -l | tr -d ' ') file(s):"
printf '  %s\n' $ZIPS

if [ "$FOUND" -lt "${#URLS[@]}" ]; then
  echo "WARNING: expected ${#URLS[@]} file(s), found $FOUND. The importer will report" >&2
  echo "         which categories are missing against the manifest." >&2
fi

# copy anything that landed on the Desktop into ~/Downloads where the importer scans
while IFS= read -r z; do
  case "$z" in
    "$DOWNLOADS"/*) : ;;
    *) cp "$z" "$DOWNLOADS/$(basename "$z")" && echo "Copied to $DOWNLOADS/$(basename "$z")" ;;
  esac
done <<< "$ZIPS"

# --- step 4: run the importer ---
# claude-sync is a zsh alias (~/.zshrc), invisible to this non-interactive shell.
echo "Running claude-sync..."
~/projects/private/claude-conversations/sync
